// Preserve unresolved Mainloop sends as uncertainty when reconciling a scheduled cancellation.
func (q *Queries) ListCancelledSessionSends(ctx context.Context, sessionID string) ([]Delivery, error) {
	rows, err := q.db.Query(ctx, listCancelledSessionSends, sessionID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Delivery{}
	for rows.Next() {
		var i Delivery
		if err := rows.Scan(
			&i.ID,
			&i.IdempotencyKey,
			&i.SessionID,
			&i.State,
			&i.Source,
			&i.TaskID,
			&i.EvidenceRef,
			&i.Detail,
			&i.OutcomeVersion,
			&i.KagentSessionID,
			&i.HealthTracked,
			&i.Attempts,
			&i.CreateFailures,
			&i.NextAttemptAt,
			&i.LeaseOwner,
			&i.LeaseUntil,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.SentText,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

